using System;using System.Threading;using System.Threading.Tasks;using IslandIntegrated;using IslandMedia;
class LyricsFallbackTests {
 static void Check(bool x,string m){if(!x)throw new Exception(m);Console.WriteLine("PASS "+m);}
 static Snapshot Song(){return new Snapshot{SourceId="cloudmusic.exe",Title="Fixture",Artist="Artist",Album="Private Album",DurationSeconds=120};}
 static string Row(string artist="Artist",int duration=120){return "[{\"id\":1,\"trackName\":\"Fixture\",\"artistName\":\""+artist+"\",\"duration\":"+duration+",\"syncedLyrics\":\"[00:01.00]line\"}]";}
 static int Main(){int first=0,second=0;string called=""; var p=new LrclibSource(true,(u,t)=>{first++;return Task.FromResult(new LyricHttpResult{Status=200,Body="[]"});});var b=new LrclibSource(true,(u,t)=>{second++;called=u.ToString();return Task.FromResult(new LyricHttpResult{Status=200,Body=Row()});},null,null,true);using(var both=new LyricsCombinedSource(p,b)){var result=both.ReadAsync(Song(),CancellationToken.None,true).Result;Check(result.State=="ready"&&first==1&&second==1,"fallback returns matching timed lyrics");Check(called.StartsWith("https://api.amll.dev/v1/lrclib/search?")&&!called.Contains("Private")&&!called.Contains("album"),"fallback sends only title and artist");}
 p=new LrclibSource(true,(u,t)=>Task.FromResult(new LyricHttpResult{Status=200,Body=Row()}));b=new LrclibSource(true,(u,t)=>{throw new Exception("backup called on primary success");},null,null,true);using(var both=new LyricsCombinedSource(p,b))Check(both.ReadAsync(Song(),CancellationToken.None,true).Result.State=="ready","primary success avoids backup");
 p=new LrclibSource(true,(u,t)=>Task.FromResult(new LyricHttpResult{Status=200,Body="[]"}));b=new LrclibSource(true,(u,t)=>Task.FromResult(new LyricHttpResult{Status=200,Body=Row("Wrong")} ),null,null,true);using(var both=new LyricsCombinedSource(p,b))Check(both.ReadAsync(Song(),CancellationToken.None,true).Result.State=="not-found","wrong artist rejected");
 p=new LrclibSource(true,(u,t)=>Task.FromResult(new LyricHttpResult{Status=200,Body="[]"}));b=new LrclibSource(true,(u,t)=>Task.FromResult(new LyricHttpResult{Status=200,Body=Row("Artist",180)}),null,null,true);using(var both=new LyricsCombinedSource(p,b))Check(both.ReadAsync(Song(),CancellationToken.None,true).Result.State=="not-found","wrong duration rejected");
 p=new LrclibSource(true,(u,t)=>Task.FromResult(new LyricHttpResult{Status=429,RetryAfter="120"}));b=new LrclibSource(true,(u,t)=>{throw new Exception("backup called on rate limit");},null,null,true);using(var both=new LyricsCombinedSource(p,b))Check(both.ReadAsync(Song(),CancellationToken.None,true).Result.State=="rate-limited"&&both.RetryNotBefore.HasValue,"primary backoff respected");return 0;}
}
